72	func mergeDSN(baseDSN string) (string, error) {
73		config, err := mysql.ParseDSN(baseDSN)
74		if err != nil {
75			return "", errors.Wrapf(err, "failed to parse DSN: %s", baseDSN)
76		}
77	
78		config.MultiStatements = true
79		return config.FormatDSN(), nil
80	}
